Consider running an algorithm individually without data sharing.
For any $0 \le \paramexplore \le 1$, the expected regret of the UCB algorithm $\algoucb_\paramexplore$ satisfies
\begin{align*}
    \Expect[\regret_T(\algoucb_\paramexplore)] =\begin{cases}
        \Theta(\log \horizon) &\text{if } \paramexplore = 0,\\

        \Theta(\horizon^\paramexplore) &\text{if } 0 < \paramexplore \le 1.
    \end{cases}
\end{align*}

For any $0 \le \paramexplore \le 1$, the expected regret of the UCB algorithm $\algoucb_\paramexplore$ satisfies
\begin{align*}
    \Expect[\regret_T(\algoucb_\paramexplore)] =\begin{cases}
        \Theta(\log \horizon) &\text{if } \paramexplore = 0,\\

        \Theta(\horizon^\paramexplore) &\text{if } 0 < \paramexplore \le 1.

The expected regret of the \egreedy algorithm $\algoegreedy_{\paramexplore, \Const}$ with $C\ge\max\left\{120K,\frac{16K}{\gapmin^2}\right\}$ satisfies
\begin{align*}
    \Expect[\regret_T(\algoegreedy_{\paramexplore,\Const})] =\begin{cases}
         \Theta(\log \horizon) &\text{if } \paramexplore = 0,\\

         \Theta(\horizon^\paramexplore) &\text{if } 0 < \paramexplore \le 1.
    \end{cases}
\end{align*}

When we jointly run the greedy algorithm $\algogreedy$ and the \egreedy algorithm $\algoegreedy_{\alpha, C}$ with $C\ge\max \left\{80K,\frac{32K}{\gapmin^2}\right\}$, the expected regrets of the two algorithms under data sharing satisfy
\begin{subequations}
\begin{align}
     & \EE{R_T(\algogreedy\mid(\algogreedy,\algoegreedy_{\alpha, \Const}))} = O(1),\label{eq:thm_violate_grd_egreedy_ub}

& \EE{R_T(\algoegreedy_{\alpha, \Const} \given (\algogreedy,\algoegreedy_{\alpha, \Const}))} = \begin{cases}
        \Omega( \log T) & \text{if } \alpha = 0,\\

        \Omega(T^\alpha) & \text{if } 0 < \alpha \le 1.\label{eq:thm_violate_egreedy_greedy_lb}

When we jointly run the greedy algorithm $\algogreedy$ and the UCB algorithm $\algoucb_\alpha$, the expected regrets of the two algorithms under data sharing satisfy 
\begin{subequations}
\begin{align}
    & \EE{R_T(\algogreedy \mid (\algogreedy, \algoucb_\alpha))} 
    = O(1), \label{eq:thm_violate_ucb_greedy_ub}

&\EE{R_T(\algoucb_\alpha \mid (\algogreedy, \algoucb_\alpha))} 
    = \begin{cases} \Omega(\log T) & \text{if } \alpha = 0,\\
    \Omega(T^\alpha) & \text{if } 0 < \alpha \le 1.
    \end{cases}\label{eq:thm_violate_ucb_greedy_lb}

Let $\const > 0$ be a constant that depends only on $\numarms, \{\gap_\idxarm\}_{\idxarm\in [\numarms]}, \paramexplore$ and $C$. Consider jointly running the greedy algorithm with any anytime algorithm $\algo$. Suppose that for any $\horizon\ge 1$, the algorithm $\algo$ satisfies
\begin{align}
    \Prob\left(\varnumpulls_{\idxarmbest, \horizon}(\algo\given (\algo, \algogreedy)) \le \frac{4}{\gapmin^2}\log\horizon\right) < \frac{\const}{\horizon^2}.\label{eq:assume_high_probability_bound}
\end{align}
Then under data sharing, the regret incurred by the greedy algorithm satisfies
\begin{align*}
    \Expect\left[\regret_\horizon(\algogreedy\given (\algo, \algogreedy))\right] <\const',
\end{align*}

Then the expected total regret under data sharing satisfies  
\begin{align}\label{eq:regret_rampup_pair_egreedy}
      \EE{R^\probassign(\algotot \mid(\algoegreedy_{\alpha_1, C}, \algoegreedy_{\alpha_2, C})} 
 = \begin{cases}
        \Theta( \log T) & \text{if } \alpha_1 = 0 \text{ and } \alpha_2+\beta \le 1,\\

        \Theta(T^{\max\cb{\alpha_1,  \alpha_2 + \beta-1}}) & \text{otherwise.}

Consider jointly running the greedy algorithm $\algogreedy$ and the EXP3 algorithm $\algoexp$ under one-way data sharing, where only the EXP algorithm supplies data to the greedy algorithm. The expected regrets of the two algorithms under one-way data sharing satisfy
\begin{subequations}
\begin{align}
   & \EE{R_T(\algogreedy \mid \algoexp\rightarrow \algogreedy )} = O(1), \label{eq:thm_violate_grd_exp_ub}\\
   & \EE{\regret_\horizon(\algoexp \mid \algoexp\rightarrow \algogreedy)}= \Omega(T^{2/3}).\label{eq:thm_violate_grd_exp_lb}

Consider any $\paramexplore\in [0, 1]$. When we jointly run the UCB algorithm $\algoucb_\paramexplore$ with any other algorithm $\mathcal{A}$, the expected regret of $\algoucb_\paramexplore$ satisfies
\begin{align*}
    &\EE{R_T(\algoucb_\paramexplore \mid (\mathcal{A}, \algoucb_\paramexplore))} 
= \begin{cases}
    O( \log T)  & \text{if } \alpha = 0, \\
    O( T^\alpha) & \text{if } 0 < \alpha \le 1.
    \end{cases}
\end{align*}

Consider any $\paramexplore\in [0, 1]$. When we jointly run the UCB algorithm $\algoucb_\paramexplore$ with any other algorithm $\algo$, the sum of the expected regrets of the two algorithms satisfies
\begin{align*}
&\EE{R_T(\algoucb_\paramexplore \mid (\algo, \algoucb_\paramexplore))} + \EE{R_T(\algo \mid (\algo, \algoucb_\paramexplore))} 
= \begin{cases}
    \Omega( \log T) & \text{if } \alpha = 0, \\
    \Omega( T^\alpha) & \text{if } 0 < \alpha \le 1.
\end{cases}
\end{align*}

Consider any $\paramexplore\in [0, 1]$ and any $C \ge \max\{120K,\, 32K/\gapmin^2\}$. When we jointly run the \egreedy algorithm $\algoegreedy_{\paramexplore, C}$ with any other algorithm $\mathcal{A}$, the expected regret of $\algoegreedy_\paramexplore$ satisfies
\begin{align*}
    &\EE{R_T(\algoegreedy_\paramexplore \mid (\mathcal{A}, \algoegreedy_\paramexplore))} 
= \begin{cases}
    O( \log T)  & \text{if } \alpha = 0, \\
    O( T^\alpha) & \text{if } 0 < \alpha \le 1.
    \end{cases}
\end{align*}

Consider any $\paramexplore\in [0, 1]$ and any $C > 0$. When we jointly run the \egreedy algorithm $\algoegreedy_{\paramexplore, C}$ with any other algorithm $\mathcal{A}$, then the expected regret of $\algoegreedy_{\paramexplore, C}$ satisfies
    \begin{align*}
        \Expect[\regret_\horizon(\algoegreedy_\paramexplore)\given (\algo, \algoegreedy_\paramexplore)] = \begin{cases}
            \Omega(\log\horizon) & \text{if }\paramexplore=0,\\
            \Omega(\horizon^\paramexplore) & \text{if } 0 < \paramexplore \le 1.
        \end{cases}
    \end{align*}

Consider any $\paramexplore\in [0, 1]$ and any $\probassign\in (0, 1)$. Under a Bernoulli assignment, we jointly run the UCB algorithm $\algoucb_\paramexplore$ with any other algorithm $\mathcal{A}$, where the probability of the UCB algorithm is $\probassign$. The expected regret of $\algoucb_\paramexplore$ satisfies
\begin{align*}
    &\EE{R_T(\algoucb_\paramexplore \mid (\mathcal{A}, \algoucb_\paramexplore))} 
= \begin{cases}
    O( \log T)  & \text{if } \alpha = 0, \\
    O( T^\alpha) & \text{if } 0 < \alpha \le 1.
    \end{cases}
\end{align*}

Let $\const > 0$ be a constant that depends only on $\numarms$ and $\{\gap_\idxarm\}_{\idxarm\in [\numarms]}$. Consider jointly running the greedy algorithm with any anytime algorithm $\algo$ under one-way data sharing, where the greedy algorithm has access to data from algorithm $\algo$, but algorithm $\algo$ does not have access to data from the greedy algorithm. Suppose that for any $\horizon \ge 1$, algorithm $\algo$ satisfies
\begin{align}
    \Prob\left(\varnumpulls_{\idxarmbest,T}(\algo) \le \frac{4}{\gapmin^2}\log\horizon\right) < \frac{\const}{\horizon^2}.\label{eq:assume_high_probability_bound_one_way}
\end{align}
